// Repro: Render Carbon’s Accordion & Button skeletons with no accessible name
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';

function SkeletonAccordionAndButton() {
  return (
    <div style={{ padding: '3rem', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      {/* Accordion Skeleton */}
      <h2>Accordion Skeleton</h2>
      <ul className="bx--accordion bx--skeleton" style={{ width: '500px' }}>
        {[1, 2, 3].map(i => (
          <li className="bx--accordion__item bx--skeleton" key={i}>
            {/* button has no text or aria-label */}
            <button className="bx--accordion__heading" type="button"></button>
            <div className="bx--accordion__content">
              {/* skeleton text placeholders */}
              <p className="bx--skeleton__text" style={{ width: '90%' }}></p>
              <p className="bx--skeleton__text" style={{ width: '80%' }}></p>
            </div>
          </li>
        ))}
      </ul>

      {/* Button Skeleton */}
      <h2 style={{ marginTop: '2rem' }}>Button Skeleton</h2>
      {/* button with no text or aria-label */}
      <button className="bx--btn bx--skeleton" type="button"></button>
    </div>
  );
}

ReactDOM.render(
  <SkeletonAccordionAndButton />,
  document.getElementById('root')
);
